#include <bits/stdc++.h>

using namespace std;

int main(void) {
	int n, m;
	vector<pair<int, int> > p;
	vector<int>a, b;
	set<int>s;
	int x, y;
	int l, r;
	cin >> n >> m;
	for (int i = 0; i < m; i++) {
		cin >> x >> y;
		p.push_back({ x,y });
	}
	sort(p.begin(), p.end());
	s.insert(n);
	l = 0;
	while (l < m) {
		a.clear();
		b.clear();
		r = l;
		while (r < m) {
			if (p[r].first == p[l].first)r++;
			else break;
		}
		for (int i = l; i < r; i++) {
			y = p[i].second;
			if (((s.find(y - 1) != s.end()) || (s.find(y + 1) != s.end())) && (s.find(y) == s.end()))a.push_back(y);
			if (((s.find(y - 1) == s.end()) && (s.find(y + 1) == s.end())) && (s.find(y) != s.end()))b.push_back(y);
		}
		for (int i = 0; i < a.size(); i++)s.insert(a[i]);
		for (int i = 0; i < b.size(); i++)s.erase(b[i]);
		l = r;
	}
	cout << s.size() << endl;
}
